    #[test]
    fn git_branch_fresh_cache_returns_cached_value() {
        let detected_at = Instant::now();
        let mut cache = Some((Some(GitBranch::Ok("cached-branch".to_string())), detected_at));

        let branch = git_branch_cached(&mut cache);

        assert!(matches!(&branch, Some(GitBranch::Ok(b)) if b == "cached-branch"));
        // A re-detection would have replaced the timestamp; a fresh hit must not.
        let (_, at) = cache.as_ref().unwrap();
        assert_eq!(*at, detected_at);
    }

    #[test]
    fn git_branch_fresh_cache_keeps_none_result() {
        let detected_at = Instant::now();
        let mut cache = Some((None, detected_at));

        let branch = git_branch_cached(&mut cache);

        // A cached `None` (not a repo) must be served without re-spawning.
        assert!(branch.is_none());
        let (_, at) = cache.as_ref().unwrap();
        assert_eq!(*at, detected_at);
    }

    #[test]
    fn git_branch_stale_cache_redetects() {
        let stale = Instant::now().checked_sub(Duration::from_secs(2)).unwrap();
        let mut cache = Some((Some(GitBranch::Ok("cached-branch".to_string())), stale));

        let _ = git_branch_cached(&mut cache);

        // The returned value is environment-dependent (real `git` spawn), so
        // assert only that the cache was refreshed.
        let (_, at) = cache.as_ref().unwrap();
        assert!(at > &stale, "stale cache must be re-detected");
    }

    #[test]
    fn git_branch_empty_cache_detects_and_stores() {
        let before = Instant::now();
        let mut cache: Option<(Option<GitBranch>, Instant)> = None;

        let _ = git_branch_cached(&mut cache);

        // Whatever the environment yields (Ok in a repo, None/Error outside),
        // a result must have been stored with a fresh timestamp.
        let (_, at) = cache.as_ref().unwrap();
        assert!(at >= &before);
    }
